package com.aistock.gateway.adminmarket;
import com.aistock.gateway.*;import com.aistock.gateway.statistics.StatisticsIdentityClient;import com.aistock.common.*;import com.sun.net.httpserver.HttpServer;import java.net.*;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.boot.test.mock.mockito.MockBean;import org.springframework.test.context.*;import org.springframework.test.annotation.DirtiesContext;import org.springframework.test.web.servlet.MockMvc;import jakarta.servlet.http.Cookie;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest(properties={"spring.cloud.nacos.discovery.enabled=false","spring.cloud.loadbalancer.retry.enabled=false","aistock.market.url=","aistock.scheduler.url=","SERVICE_TOKEN=test-only"}) @AutoConfigureMockMvc @DirtiesContext
class AdminMarketRefreshDiscoveryTest {
 static final AtomicInteger schedulerCalls=new AtomicInteger(),marketCalls=new AtomicInteger();static final HttpServer SCHEDULER=start(schedulerCalls),MARKET=start(marketCalls);
 static HttpServer start(AtomicInteger counter){try{var s=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);s.createContext("/api/v1/",x->{counter.incrementAndGet();var b="{\"code\":\"OK\",\"data\":{\"queriedAt\":\"2026-10-27T12:00:00Z\",\"instrumentId\":\"SH600030\",\"actionsEnabled\":false,\"allowed\":false,\"policyVersion\":\"admin-market-refresh-v1\"}}".getBytes(java.nio.charset.StandardCharsets.UTF_8);x.sendResponseHeaders(200,b.length);x.getResponseBody().write(b);x.close();});s.start();return s;}catch(java.io.IOException e){throw new IllegalStateException(e);}}
 @DynamicPropertySource static void properties(DynamicPropertyRegistry r){r.add("spring.cloud.discovery.client.simple.instances.stock-scheduler-service[0].uri",()->"http://127.0.0.1:"+SCHEDULER.getAddress().getPort());r.add("spring.cloud.discovery.client.simple.instances.stock-market-service[0].uri",()->"http://127.0.0.1:"+MARKET.getAddress().getPort());}
 @Autowired MockMvc mvc;@MockBean StatisticsIdentityClient identity;
 @AfterAll static void stop(){SCHEDULER.stop(0);MARKET.stop(0);}
 @Test void explicitRoutesUseDistinctDiscoveredServices()throws Exception{when(identity.resolve(any(),anyString())).thenReturn(ApiResponse.success(new StatisticsIdentityClient.Identity(UUID.randomUUID(),"ADMIN",1),"t"));mvc.perform(get("/api/v1/admin/market-data/SH600030/refresh-options").cookie(new Cookie("AISTOCK_SESSION","s"))).andExpect(status().isOk());assertEquals(1,schedulerCalls.get());assertEquals(0,marketCalls.get());mvc.perform(get("/api/v1/admin/market-data").cookie(new Cookie("AISTOCK_SESSION","s"))).andExpect(status().isOk());assertEquals(1,marketCalls.get());assertEquals(1,schedulerCalls.get());}
}
